#include <memory>
#include <mutex>
#include <atomic>
#include <thread>
#include <queue>
#include <functional>
#include <condition_variable>
#include <cassert>
#include <cstring>
#include <iostream>

namespace db {

struct ConnectionHandle {
    int fd;
    char host[256];
    bool authenticated;
};

class ResultSet {
public:
    ResultSet(const char* data, size_t len) : data_(new char[len]), len_(len) {
        memcpy(data_, data, len);
    }
    ~ResultSet() { delete[] data_; }
    const char* data() const { return data_; }
    size_t size() const { return len_; }
private:
    char* data_;
    size_t len_;
};

class ConnectionPool;

class Connection {
public:
    enum class State { IDLE, ACTIVE, DRAINING, CLOSED };

    Connection(ConnectionPool* pool, int id)
        : pool_(pool), id_(id), state_(State::IDLE), handle_(nullptr) {}

    ~Connection() { close(); }

    bool open(const char* host, int port) {
        std::lock_guard<std::mutex> lock(mu_);
        handle_ = std::make_unique<ConnectionHandle>();
        handle_->fd = id_ * 100 + port;
        strncpy(handle_->host, host, sizeof(handle_->host) - 1);
        handle_->host[sizeof(handle_->host) - 1] = '\0';
        handle_->authenticated = true;
        state_ = State::ACTIVE;
        return true;
    }

    std::unique_ptr<ResultSet> execute(const char* query) {
        std::lock_guard<std::mutex> lock(mu_);
        if (state_ != State::ACTIVE) return nullptr;
        if (!handle_ || !handle_->authenticated) return nullptr;
        // Simulate query execution
        return std::make_unique<ResultSet>(query, strlen(query));
    }

    void beginDrain() {
        std::lock_guard<std::mutex> lock(mu_);
        if (state_ == State::ACTIVE) {
            state_ = State::DRAINING;
        }
    }

    void close() {
        std::lock_guard<std::mutex> lock(mu_);
        handle_.reset();
        state_ = State::CLOSED;
    }

    State state() const { return state_; }
    int id() const { return id_; }

    ConnectionHandle* rawHandle() {
        // No lock - caller is responsible for synchronization
        return handle_.get();
    }

private:
    ConnectionPool* pool_;
    int id_;
    State state_;
    std::unique_ptr<ConnectionHandle> handle_;
    std::mutex mu_;
};

class ConnectionPool {
public:
    ConnectionPool(size_t maxConns) : maxConns_(maxConns), shuttingDown_(false) {}

    ~ConnectionPool() { shutdown(); }

    bool initialize(const char* host, int port) {
        std::lock_guard<std::mutex> lock(poolMu_);
        for (size_t i = 0; i < maxConns_; i++) {
            auto conn = std::make_shared<Connection>(this, i);
            conn->open(host, port);
            connections_.push_back(conn);
        }
        return true;
    }

    std::shared_ptr<Connection> acquire() {
        std::lock_guard<std::mutex> lock(poolMu_);
        if (shuttingDown_) return nullptr;
        for (auto& conn : connections_) {
            if (conn->state() == Connection::State::ACTIVE) {
                return conn;
            }
        }
        return nullptr;
    }

    void shutdown() {
        std::unique_lock<std::mutex> lock(poolMu_);
        if (shuttingDown_) return;
        shuttingDown_ = true;

        // Phase 1: Begin draining all connections
        for (auto& conn : connections_) {
            conn->beginDrain();
        }

        // Phase 2: Allow in-flight operations to complete
        lock.unlock();
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
        lock.lock();

        // Phase 3: Close all connections
        for (auto& conn : connections_) {
            conn->close();
        }
    }

    // Health check iterates raw handles for monitoring
    bool healthCheck() {
        std::lock_guard<std::mutex> lock(poolMu_);
        for (auto& conn : connections_) {
            ConnectionHandle* h = conn->rawHandle();
            // During shutdown, draining connections still have valid handles
            // We check state to skip closed ones
            if (conn->state() == Connection::State::CLOSED) continue;
            // Access the handle - if connection was drained but not yet closed,
            // handle should still be valid
            if (h->fd < 0) return false;
            if (!h->authenticated) return false;
        }
        return true;
    }

private:
    size_t maxConns_;
    std::atomic<bool> shuttingDown_;
    std::vector<std::shared_ptr<Connection>> connections_;
    std::mutex poolMu_;
};

// Driver facade
class DatabaseDriver {
public:
    DatabaseDriver() : pool_(std::make_unique<ConnectionPool>(4)) {}

    bool connect(const char* host, int port) {
        return pool_->initialize(host, port);
    }

    std::unique_ptr<ResultSet> query(const char* sql) {
        auto conn = pool_->acquire();
        if (!conn) return nullptr;
        return conn->execute(sql);
    }

    bool isHealthy() {
        return pool_->healthCheck();
    }

    void gracefulShutdown() {
        pool_->shutdown();
    }

private:
    std::unique_ptr<ConnectionPool> pool_;
};

} // namespace db

int main() {
    db::DatabaseDriver driver;
    driver.connect("localhost", 5432);

    // Simulate concurrent health check during shutdown
    std::thread monitor([&driver]() {
        for (int i = 0; i < 100; i++) {
            driver.isHealthy();
            std::this_thread::sleep_for(std::chrono::milliseconds(1));
        }
    });

    std::this_thread::sleep_for(std::chrono::milliseconds(5));
    driver.gracefulShutdown();

    monitor.join();
    return 0;
}
